package erratum

func Use(opener ResourceOpener, input string) error {
	var res Resource
	var err error
	for {
		res, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if errors.As(err, &te) {
			continue
		}
		return err
	}
	defer res.Close()
	defer func() {
		if r := recover(); r != nil {
			if fe, ok := r.(FrobError); ok {
				res.Defrob(fe.defrobTag)
			}
			err = r.(error)
		}
	}()
	res.Frob(input)
	return err
}
```

Wait — Defrob must be called before Close. With defer, the execution order is LIFO: the recover defer is registered after the Close defer, so recover runs first, then Close. Good — Defrob happens before Close.

But note: the recover function assigns to `err`. If r is not an error (e.g., a string panic), r.(error) will be nil. The tests only panic with errors. But to be safe: if r is not an error, we can wrap it. Let's keep it simple and robust:

