package erratum

import (
	"errors"
	"fmt"
)

// Use opens a resource via opener, calls Frob(input) on it, and ensures the
// resource is closed exactly once in all cases.
//
// If opener fails with a TransientError, it keeps retrying. Any other error
// is returned. If Frob panics with a FrobError, Defrob is called with the
// panic's defrobTag before the resource is closed, and the error is returned.
func Use(opener ResourceOpener, input string) error {
	var res Resource
	var err error

	for {
		res, err = opener()
		if err == nil {
			break
		}
		var transient TransientError
		if errors.As(err, &transient) {
			continue
		}
		return err
	}

	defer res.Close()

	defer func() {
		if recovered := recover(); recovered != nil {
			if frobError, ok := recovered.(FrobError); ok {
				res.Defrob(frobError.defrobTag)
			}
			if e, ok := recovered.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("panic: %v", recovered)
			}
		}
	}()

	res.Frob(input)
	return err
}

